/**
 * База знаний «Анализа этикетки» (nj646_label) — СТАРТОВЫЙ набор ингредиентов.
 *
 * Это не «истина в последней инстанции», а проверяемая стартовая база: после
 * первого запуска она засевается в таблицу `nj_646_ingredients`, и дальше
 * живёт в базе — с правками посетителей, черновиками ИИ и накопленной
 * статистикой встреч. Конфиг — только посев (Service_Nj646_Seed).
 *
 * Легенда полей:
 *   'ru'   — название по-русски;
 *   'int'  — международное/INCI/английское название;
 *   'kind' — food | cosmetic | both;
 *   'risk' — 0 полезно/безопасно, 1 нейтрально, 2 осторожно (аллергия,
 *            раздражение, спорность), 3 риск (эндокринные/канцерогенные
 *            подозрения, сильные аллергены), 4 избегать;
 *   'verdict' — useful | neutral | caution | risky | avoid;
 *   'cat'  — категория (консервант, краситель, ПАВ, эмолент…);
 *   'e'    — номер E/INS для пищевых добавок;
 *   'sum'  — одно предложение для карточки;
 *   'det'  — пояснение подробнее (может быть пустым);
 *   'syn'  — синонимы и варианты написания (по ним работает сопоставление);
 *   'avoid'— коды риска для профиля: allergy, pregnancy, vegan, diabetes,
 *            hypertension, kids, sensitive, acne, dry, oily;
 *   'src'  — источники: EFSA, FDA, ВОЗ, SCCS, CIR, IARC, EU Cosmetics.
 *
 * ВАЖНО: сервис носит справочный характер и не заменяет врача или
 * дерматолога. Формулировки рисков умышленно осторожные: «обсуждается»,
 * «может», «у людей с чувствительностью».
 */

return [

    // ---------------------------------------------------------------- лимиты
    'limits' => [
        'text_max'        => (int) (getenv('NJ646_MAX_TEXT_CHARS') ?: 8000),
        'items_max'       => (int) (getenv('NJ646_MAX_ITEMS') ?: 120),
        'analyses_per_hour' => (int) (getenv('NJ646_ANALYSES_PER_HOUR') ?: 30),
        'photo_per_hour'  => (int) (getenv('NJ646_PHOTO_PER_HOUR') ?: 10),
        'photo_mb'        => (int) (getenv('NJ646_MAX_PHOTO_MB') ?: 8),
        // Пределы ЗАПИСИ (килобайты): text_max ограничивает вставку в форме, а
        // это — страховка колонки, если текст пришёл другим путём или лимит
        // формы поднят. Обрезка честная: пометка в `about.cut` и на странице.
        'raw_text_kb'     => (int) (getenv('NJ646_MAX_RAW_TEXT_KB') ?: 64),
        'result_kb'       => (int) (getenv('NJ646_MAX_RESULT_KB') ?: 256),
        'study_per_day'   => (int) (getenv('NJ646_STUDY_PER_DAY') ?: 10),
        'unknown_min_seen' => (int) (getenv('NJ646_UNKNOWN_MIN_SEEN') ?: 2),
        'unknown_per_run' => (int) (getenv('NJ646_UNKNOWN_PER_RUN') ?: 3),   // сколько неизвестных изучаем за разбор
        'history_len'     => 12,
        'corrections_per_day' => 20,
        // Через сколько секунд прогон, стоящий в очереди и никем не взятый,
        // честно говорит об этом на странице (воркер не запущен/канала нет в
        // WORKER_CHANNELS). Без этого фото «распознавалось» бесконечно.
        'stall_hint_sec'  => 150,

        // Развёрнутый ответ: разбор не заканчивается первой оценкой. Незнакомые
        // вещества уходят на изучение сразу (не дожидаясь второго упоминания),
        // страница показывает ход изучения, а когда карточки готовы —
        // пересчитывает оценку уже по пополненной базе. Владелец (03.10.2026):
        // «нужен режим, при котором пользователь всё-таки получает развёрнутый
        // ответ: этикетка распозналась — вещества определились — неизвестные
        // изучились — пользователю дан ответ».
        'detailed'         => trim((string) getenv('NJ646_DETAILED')) === '' ? 1 : max(0, min(1, (int) getenv('NJ646_DETAILED'))),
        // Сколько незнакомых веществ изучаем за один разбор в этом режиме
        // (в обычном — unknown_per_run, и только со второго упоминания).
        'detailed_studies' => max(1, min(8, (int) (getenv('NJ646_DETAILED_STUDIES') ?: 3))),
        // Сколько секунд страница ждёт изучение, прежде чем честно показать
        // промежуточный ответ («эти N веществ ещё изучаются»).
        'detailed_wait_sec' => max(10, min(180, (int) (getenv('NJ646_DETAILED_WAIT_SEC') ?: 45))),

        // ПОЛНЫЙ ОТВЕТ (NJ646_FULL_ANSWER). Отличие от развёрнутого: там на
        // разбор уходит пачка `detailed_studies` (3), а здесь — ВСЕ незнакомые
        // вещества, и ответ не считается готовым, пока каждое из них не
        // разобрано. Владелец (03.10.2026): «режим, при котором пользователю
        // выдаётся полный готовый ответ (то что есть + автоматически изучается
        // всё неизученное — полный ответ)». Включается в конфиге; по умолчанию
        // ВЫКЛЮЧЕН: он дороже — один разбор может стоить десятки запросов к
        // модели, поэтому в бою его включают осознанно.
        'full_answer'     => max(0, min(1, (int) (getenv('NJ646_FULL_ANSWER') ?: 0))),
        // Сколько незнакомых веществ изучаем за один разбор в полном режиме.
