        // случай, когда модель общая и на неё есть другие потребители.
        'full_studies'    => max(0, min(50, (int) (getenv('NJ646_FULL_STUDIES') ?: 0))),
        // Сколько страница ждёт карточки, прежде чем показать промежуточный
        // ответ (дальше она продолжает ждать в фоне и сама дорисовывает ответ).
        'full_wait_sec'   => max(30, min(900, (int) (getenv('NJ646_FULL_WAIT_SEC') ?: 300))),
        // Суточный лимит автоизучений в полном режиме: отдельный и выше
        // обычного (study_per_day), иначе «всё неизученное» упиралось бы в
        // лимит ручных изучений на третьем веществе.
        'full_per_day'    => max(1, min(500, (int) (getenv('NJ646_FULL_PER_DAY') ?: 60))),

        // История разборов: сколько записей показывать на странице админа
        // («последние N») и сколько своих разборов видит посетитель во вкладке
        // «Мои разборы». Владелец (03.10.2026): «добавь страницу для админа с
        // перечнем что анализировали (последние n записей), да и для
        // пользователя — последние его запросы».
        'history_admin'   => max(10, min(200, (int) (getenv('NJ646_HISTORY_ADMIN') ?: 30))),
        'history_user'    => max(5, min(50, (int) (getenv('NJ646_HISTORY_USER') ?: 20))),

